import {flattenLayers,layerTree} from './layers.js';
import {uid} from './core.js';
// Semantic presentation policy shared by inspector, hierarchy and commands.
import {isolationIds} from './model.js';
export const semanticTypes={region:{label:'Región de panel',icon:'panel',actions:['color','selectBoundary','boundaryStitch','selectParent']},panelBoundary:{label:'División de panel',icon:'edge',actions:['editNodes','double','createPanel','delete']},body:{label:'Pieza de prenda',icon:'garment',actions:['editNodes','editEdges','stitch','createPanel']},structure:{label:'Pieza de prenda',icon:'garment',actions:['editNodes','editEdges','stitch','mirror']},pocket:{label:'Bolsillo',icon:'pocket',actions:['editNodes','stitch','mirror','duplicate']},hood:{label:'Capucha',icon:'garment',actions:['editNodes','stitch','mirror','duplicate']},image:{label:'Gráfico',icon:'image',actions:['clip','mirror','flipV','front']},text:{label:'Texto',icon:'text',actions:['duplicate','mirror','front']},path:{label:'Pieza vectorial',icon:'path',actions:['editNodes','editEdges','stitch','duplicate']},rib:{label:'Rib',icon:'rib',actions:['editNodes','editConstruction','presets','removeSelectedConstruction']},construction:{label:'Construcción',icon:'stitch',actions:['selectSource','editConstruction','presets','removeSelectedConstruction']},group:{label:'Grupo',icon:'group',actions:['isolate','duplicate','dupMirror','ungroup']}};
export const commandLabels={color:'Relleno',selectBoundary:'Editar división',boundaryStitch:'Costura doble en división',selectParent:'Seleccionar pieza',editNodes:'Editar forma',editEdges:'Elegir borde',stitch:'Costura',createPanel:'Panel',mirror:'Reflejar',duplicate:'Duplicar',clip:'Recortar al cuerpo',flipV:'Reflejar Y',front:'Adelante',editConstruction:'Editar construcción',presets:'Estilo',removeSelectedConstruction:'Quitar construcción',selectSource:'Editar base',isolate:'Aislar grupo',dupMirror:'Duplicar y reflejar',ungroup:'Desagrupar',group:'Agrupar',lockSelection:'Bloquear',hideSelection:'Ocultar',back:'Atrás',delete:'Eliminar'};
export function selectionIdentity(os,groups=[]){if(os.length>1){const belongs=(o,id)=>{let current=o.group;const seen=new Set();while(current&&!seen.has(current)){if(current===id)return true;seen.add(current);current=groups.find(g=>g.id===current)?.parent;}return false;};const group=groups.find(g=>os.every(o=>belongs(o,g.id)));return {...(group?semanticTypes.group:{label:'Selección múltiple',icon:'group',actions:['group','duplicate','mirror','front']}),name:group?.name||os.length+' objetos',category:group?.category||'detail',groupId:group?.id};}const o=os[0];if(!o)return null;const key=o.construction?'construction':o.component?.kind||o.modifiers?.find(m=>m.type==='rib')?.type||(o.source?'construction':o.semanticType in semanticTypes?o.semanticType:o.category==='structure'?'structure':o.type);return {...(semanticTypes[key]||semanticTypes.path),name:o.name,category:o.category};}
export function treeSelection({ids,current,anchor,id,shift=false,toggle=false,allowed=()=>true}){const available=ids.filter(allowed);let next;if(shift&&available.includes(anchor)&&available.includes(id)){const a=available.indexOf(anchor),b=available.indexOf(id),range=available.slice(Math.min(a,b),Math.max(a,b)+1);next=toggle?[...new Set([...current,...range])]:range;}else next=toggle?(current.includes(id)?current.filter(i=>i!==id):[...current,id]):[id];return {selected:next.filter(allowed),anchor:shift?anchor||id:id};}
export function groupDescendants(p,view,id){return [...(isolationIds(p,view,id)||[])];}
export function completeSelection(p,view,ids){const set=new Set(ids);let changed=true;while(changed){changed=false;for(const o of p.views[view]){if(set.has(o.id)&&o.source&&!set.has(o.source)){set.add(o.source);changed=true;}if((set.has(o.source)||set.has(o.panelOf)||set.has(o.ownerId)||set.has(o.attachment?.source))&&!set.has(o.id)){set.add(o.id);changed=true;}}}return [...set];}
export function groupObjects(p,view,ids,id){const all=completeSelection(p,view,ids),os=p.views[view].filter(o=>all.includes(o.id));if(!os.length)return null;const g={id,name:'Grupo',category:os.every(o=>o.category===os[0].category)?os[0].category:'detail'};p.groups[view].push(g);const includedGroups=new Set(os.map(o=>o.group).filter(Boolean));for(const oldId of includedGroups){const members=groupDescendants(p,view,oldId);if(members.length&&members.every(i=>all.includes(i))){const old=p.groups[view].find(g=>g.id===oldId);if(old)old.parent=id;}}os.forEach(o=>{if(!o.group||!includedGroups.has(o.group)||!p.groups[view].find(g=>g.id===o.group)?.parent)o.group=id;});return g;}
export function ungroupObjects(p,view,ids){const targets=new Set(p.views[view].filter(o=>ids.includes(o.id)).map(o=>o.group).filter(Boolean));for(const id of targets){const g=p.groups[view].find(g=>g.id===id);for(const o of p.views[view])if(o.group===id){if(g?.parent)o.group=g.parent;else delete o.group;}for(const child of p.groups[view])if(child.parent===id){if(g?.parent)child.parent=g.parent;else delete child.parent;}p.groups[view]=p.groups[view].filter(g=>g.id!==id);}return targets;}
export function selectableTree(p,view){return flattenLayers(layerTree(p,view)).filter(r=>r.kind==='object').map(r=>r.id);}

export function copyGroupMetadata(p,view,originals,copies){const map=new Map();originals.forEach((o,i)=>{if(o.group&&copies[i]?.group)map.set(o.group,copies[i].group);});const groups=p.groups[view];for(const [oldId]of [...map]){let parent=groups.find(g=>g.id===oldId)?.parent;while(parent&&!map.has(parent)){const members=groupDescendants(p,view,parent);if(!members.every(id=>originals.some(o=>o.id===id)))break;map.set(parent,uid());parent=groups.find(g=>g.id===parent)?.parent;}}for(const [oldId,id]of map){const old=groups.find(g=>g.id===oldId);if(!old)continue;const copy={...old,id,name:old.name+' — copia'};for(const k of ['mirrorPeer','instanceOf','mirrorAxisRef'])delete copy[k];if(old.parent&&map.has(old.parent))copy.parent=map.get(old.parent);else delete copy.parent;groups.push(copy);}}

export function pruneEmptyGroups(p,view){let previous;do{previous=p.groups[view].length;p.groups[view]=p.groups[view].filter(g=>g.folder||p.views[view].some(o=>o.group===g.id)||p.groups[view].some(child=>child.parent===g.id));}while(previous!==p.groups[view].length);}
